  /** Puts the notice away for two weeks on this device. */
  public dismiss(): void {
    this.change({ dismissedAt: Date.now() });
  }

  /** Notes that the result screen offered the sign-in. */
  public markSuccessHintShown(): void {
    this.change({ successHintShown: true });
  }

  /**
